import os, sys, time, requests, json

os.environ['REQUESTS_CA_BUNDLE'] = '/etc/ssl/certs/ca-certificates.crt'
os.environ['SSL_CERT_FILE'] = '/etc/ssl/certs/ca-certificates.crt'

OID = '4d503d447028f437211880bea4ee1a7f6732113ea8560181fcca163251864794'
SIZE = 688768764
OUTFILE = '/root/autodl-tmp/libero_datasets/libero_spatial/pick_up_the_black_bowl_on_the_wooden_cabinet_and_place_it_on_the_plate_demo.hdf5'
TMPFILE = OUTFILE + '.downloading'
CHUNK = 10 * 1024 * 1024
MAX_RETRIES = 30

def get_download_url():
    lfs_url = 'https://huggingface.co/datasets/yifengzhu-hf/LIBERO-datasets.git/info/lfs/objects/batch'
    payload = {
        'operation': 'download',
        'transfers': ['basic'],
        'objects': [{'oid': OID, 'size': SIZE}]
    }
    headers = {
        'Content-Type': 'application/vnd.git-lfs+json',
        'Accept': 'application/vnd.git-lfs+json',
    }
    r = requests.post(lfs_url, json=payload, headers=headers, timeout=30)
    r.raise_for_status()
    data = r.json()
    url = data['objects'][0]['actions']['download']['href']
    print(f"Got URL host: {url.split('/')[2]}", flush=True)
    return url

def download():
    downloaded = 0
    if os.path.exists(TMPFILE):
        downloaded = os.path.getsize(TMPFILE)

    print(f"Starting from {downloaded}/{SIZE} ({downloaded/SIZE*100:.1f}%)", flush=True)

    for attempt in range(MAX_RETRIES):
        try:
            url = get_download_url()
            headers = {}
            if downloaded > 0:
                headers['Range'] = f'bytes={downloaded}-'

            r = requests.get(url, headers=headers, stream=True, timeout=(30, 120))
            if r.status_code == 416:
                break
            r.raise_for_status()

            mode = 'ab' if downloaded > 0 else 'wb'
            with open(TMPFILE, mode) as f:
                last_print = time.time()
                for chunk in r.iter_content(chunk_size=CHUNK):
                    if chunk:
                        f.write(chunk)
                        f.flush()
                        downloaded += len(chunk)
                        if time.time() - last_print > 5:
                            print(f"  {downloaded/1024/1024:.0f}MB/{SIZE/1024/1024:.0f}MB ({downloaded/SIZE*100:.1f}%)", flush=True)
                            last_print = time.time()

            if downloaded >= SIZE:
                break

        except Exception as e:
            print(f"Retry {attempt+1} at {downloaded/1024/1024:.0f}MB: {type(e).__name__}: {str(e)[:100]}", flush=True)
            time.sleep(3)

    if downloaded >= SIZE:
        os.rename(TMPFILE, OUTFILE)
        print(f"COMPLETE: {OUTFILE}", flush=True)
    else:
        print(f"FAILED: {downloaded}/{SIZE}", flush=True)
        sys.exit(1)

if __name__ == '__main__':
    if os.path.exists(OUTFILE):
        os.remove(OUTFILE)
    download()
